CREATE TABLE public.report_integrity_settings(id boolean PRIMARY KEY DEFAULT true, session_limit integer NOT NULL DEFAULT 10, network_limit integer NOT NULL DEFAULT 60,user_limit integer NOT NULL DEFAULT 15,window_minutes integer NOT NULL DEFAULT 10,challenge_after integer NOT NULL DEFAULT 3,review_threshold integer NOT NULL DEFAULT 30,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid);
GRANT SELECT ON public.report_integrity_settings TO authenticated; GRANT ALL ON public.report_integrity_settings TO service_role;
ALTER TABLE public.report_integrity_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY integrity_settings_read ON public.report_integrity_settings FOR SELECT TO authenticated USING(public.account_active(auth.uid()) AND public.has_role(auth.uid(),'admin'));
CREATE TABLE public.report_abuse_windows(key text PRIMARY KEY,hits integer NOT NULL DEFAULT 0,expires_at timestamptz NOT NULL);
GRANT ALL ON public.report_abuse_windows TO service_role;
ALTER TABLE public.report_abuse_windows ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.report_upload_reservations(key uuid PRIMARY KEY,session_hash text NOT NULL,original_path text,expected_mime text,expected_size integer,expires_at timestamptz NOT NULL DEFAULT now()+interval '2 hours',request_fingerprint text,consumed boolean NOT NULL DEFAULT false);
GRANT ALL ON public.report_upload_reservations TO service_role;
ALTER TABLE public.report_upload_reservations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.report_challenge_uses(nonce uuid PRIMARY KEY,expires_at timestamptz NOT NULL);
GRANT ALL ON public.report_challenge_uses TO service_role;
ALTER TABLE public.report_challenge_uses ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.report_integrity(issue_id uuid PRIMARY KEY REFERENCES public.issues(id),state text NOT NULL DEFAULT 'unverified',risk_score integer NOT NULL DEFAULT 0,signals jsonb NOT NULL DEFAULT '[]',request_fingerprint text,image_hash text,session_hash text,review_reason text,reviewed_by uuid,reviewed_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.report_integrity TO authenticated;GRANT ALL ON public.report_integrity TO service_role;
ALTER TABLE public.report_integrity ENABLE ROW LEVEL SECURITY;
CREATE POLICY integrity_scope_read ON public.report_integrity FOR SELECT TO authenticated USING(public.staff_can_work(auth.uid(),issue_id));
CREATE INDEX integrity_pending ON public.report_integrity(state,updated_at);
CREATE INDEX integrity_fingerprint ON public.report_integrity(request_fingerprint);
CREATE INDEX integrity_image_hash ON public.report_integrity(image_hash);
CREATE TABLE public.report_integrity_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),issue_id uuid REFERENCES public.issues(id),actor_id uuid,actor_label text NOT NULL,action text NOT NULL,reason text NOT NULL,from_state text,to_state text,from_status public.issue_status,to_status public.issue_status,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.report_integrity_audit TO authenticated;GRANT ALL ON public.report_integrity_audit TO service_role;
ALTER TABLE public.report_integrity_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY integrity_audit_scope ON public.report_integrity_audit FOR SELECT TO authenticated USING(public.staff_can_work(auth.uid(),issue_id));
CREATE OR REPLACE FUNCTION public.integrity_settings() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT to_jsonb(s)-'updated_by' FROM public.report_integrity_settings s WHERE id),'{"session_limit":10,"network_limit":60,"user_limit":15,"window_minutes":10,"challenge_after":3,"review_threshold":30}'::jsonb) $$;
REVOKE ALL ON FUNCTION public.integrity_settings() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.integrity_settings() TO service_role;
CREATE OR REPLACE FUNCTION public.admin_integrity_settings(_settings jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT public.account_active(auth.uid()) OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Active administrator required'; END IF;
IF (_settings->>'session_limit')::int NOT BETWEEN 3 AND 100 OR (_settings->>'network_limit')::int NOT BETWEEN 10 AND 1000 OR (_settings->>'user_limit')::int NOT BETWEEN 3 AND 100 OR (_settings->>'window_minutes')::int NOT BETWEEN 1 AND 60 OR (_settings->>'challenge_after')::int NOT BETWEEN 1 AND 50 OR (_settings->>'review_threshold')::int NOT BETWEEN 10 AND 100 OR NOT _settings ?& ARRAY['session_limit','network_limit','user_limit','window_minutes','challenge_after','review_threshold'] THEN RAISE EXCEPTION 'Invalid integrity settings'; END IF;
INSERT INTO public.report_integrity_settings(id,session_limit,network_limit,user_limit,window_minutes,challenge_after,review_threshold,updated_by) VALUES(true,(_settings->>'session_limit')::int,(_settings->>'network_limit')::int,(_settings->>'user_limit')::int,(_settings->>'window_minutes')::int,(_settings->>'challenge_after')::int,(_settings->>'review_threshold')::int,auth.uid()) ON CONFLICT(id) DO UPDATE SET session_limit=excluded.session_limit,network_limit=excluded.network_limit,user_limit=excluded.user_limit,window_minutes=excluded.window_minutes,challenge_after=excluded.challenge_after,review_threshold=excluded.review_threshold,updated_by=auth.uid(),updated_at=now();
INSERT INTO public.report_integrity_audit(actor_id,actor_label,action,reason) VALUES(auth.uid(),public.staff_actor_label(auth.uid()),'settings_changed',_settings::text); END $$;
REVOKE ALL ON FUNCTION public.admin_integrity_settings(jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.admin_integrity_settings(jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.consume_report_limits(_session text,_network text,_user uuid,_phase text,_nonce uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cfg jsonb; k text; n int; lim int; max_session int:=0; over_limit boolean:=false; BEGIN
IF _session !~ '^[a-f0-9]{64}$' OR _network !~ '^[a-f0-9]{64}$' OR _phase NOT IN ('upload','submit','challenge','analysis') THEN RAISE EXCEPTION 'Invalid abuse bucket'; END IF;
IF _user IS NOT NULL AND NOT public.account_active(_user) THEN RAISE EXCEPTION 'Account inactive'; END IF;
cfg:=public.integrity_settings();
DELETE FROM public.report_abuse_windows WHERE expires_at<now()-interval '1 day'; DELETE FROM public.report_challenge_uses WHERE expires_at<now();
FOR k,lim IN SELECT v.key,v.lim FROM (VALUES(_phase||':session:'||_session,(cfg->>'session_limit')::int),(_phase||':network:'||_network,(cfg->>'network_limit')::int),(_phase||':user:'||coalesce(_user::text,''),(cfg->>'user_limit')::int)) v(key,lim) WHERE v.key<>_phase||':user:' ORDER BY v.key LOOP
INSERT INTO public.report_abuse_windows(key,hits,expires_at) VALUES(k,1,now()+make_interval(mins=>(cfg->>'window_minutes')::int)) ON CONFLICT(key) DO UPDATE SET hits=CASE WHEN report_abuse_windows.expires_at<=now() THEN 1 ELSE report_abuse_windows.hits+1 END,expires_at=CASE WHEN report_abuse_windows.expires_at<=now() THEN excluded.expires_at ELSE report_abuse_windows.expires_at END RETURNING hits INTO n;
IF k=_phase||':session:'||_session THEN max_session:=n; END IF;
IF n>lim THEN over_limit:=true; END IF;
END LOOP;
IF _nonce IS NOT NULL AND NOT over_limit THEN INSERT INTO public.report_challenge_uses(nonce,expires_at) VALUES(_nonce,now()+interval '10 minutes') ON CONFLICT DO NOTHING;IF NOT FOUND THEN RETURN jsonb_build_object('allowed',false,'replay',true); END IF; END IF;
RETURN jsonb_build_object('allowed',NOT over_limit,'hits',max_session,'challenge_required',max_session>(cfg->>'challenge_after')::int,'window_minutes',(cfg->>'window_minutes')::int);
END $$;
REVOKE ALL ON FUNCTION public.consume_report_limits(text,text,uuid,text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.consume_report_limits(text,text,uuid,text,uuid) TO service_role;
DO $wrap$ DECLARE s text; BEGIN s:=pg_get_functiondef('public.create_civic_report(jsonb,text)'::regprocedure);s:=replace(s,'FUNCTION public.create_civic_report(','FUNCTION public.create_civic_report_core(');EXECUTE s; END $wrap$;
REVOKE ALL ON FUNCTION public.create_civic_report_core(jsonb,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.create_civic_report_core(jsonb,text) TO service_role;
CREATE OR REPLACE FUNCTION public.create_civic_report(_report jsonb,_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; i public.issues; reservation public.report_upload_reservations; prior public.report_integrity; fingerprint text; imagehash text; signals jsonb:='[]';score int:=0;cfg jsonb; nextstate text; BEGIN
IF length(trim(coalesce(_report->>'title','')))<3 OR length(_report->>'title')>120 OR length(coalesce(_report->>'description',''))>1000 OR length(coalesce(_report->>'summary',''))>600 OR _report->>'category' NOT IN ('roads','electricity','water','drainage','waste','transport','parks','sanitation','trees','buildings','other') OR _report->>'status' NOT IN ('submitted','needs_classification') OR _token !~ '^[a-f0-9]{48}$' THEN RAISE EXCEPTION 'Invalid report fields'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.ward_at_point((_report->>'lat')::float8,(_report->>'lng')::float8)) THEN RAISE EXCEPTION 'Incident location outside supported wards'; END IF;
fingerprint:=_report->>'integrity_fingerprint';imagehash:=_report->>'integrity_image_hash';
IF fingerprint IS NULL OR fingerprint !~ '^[a-f0-9]{64}$' OR _report->>'integrity_session' IS NULL THEN RAISE EXCEPTION 'Verified submission reservation required'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended('integrity:'||coalesce(imagehash,fingerprint),0));
SELECT * INTO reservation FROM public.report_upload_reservations WHERE key=(_report->>'idempotency_key')::uuid FOR UPDATE;
IF reservation.key IS NULL OR reservation.session_hash IS DISTINCT FROM _report->>'integrity_session' THEN RAISE EXCEPTION 'Submission reservation unavailable'; END IF;
SELECT * INTO i FROM public.issues WHERE idempotency_key=_report->>'idempotency_key';
IF i.id IS NOT NULL THEN SELECT * INTO prior FROM public.report_integrity WHERE issue_id=i.id; IF prior.request_fingerprint IS DISTINCT FROM fingerprint OR prior.session_hash IS DISTINCT FROM reservation.session_hash THEN RAISE EXCEPTION 'Submission retry does not match the original'; END IF;RETURN jsonb_build_object('ref',i.ref_code,'duplicate',true); END IF;
IF reservation.expires_at<now() OR reservation.consumed THEN RAISE EXCEPTION 'Submission reservation expired'; END IF;
IF _report->>'original_path' IS NOT NULL AND (reservation.original_path IS DISTINCT FROM _report->>'original_path' OR imagehash IS NULL) THEN RAISE EXCEPTION 'Photo reservation mismatch'; END IF;
cfg:=public.integrity_settings();
IF imagehash IS NOT NULL AND EXISTS(SELECT 1 FROM public.report_integrity r JOIN public.issues x ON x.id=r.issue_id WHERE r.image_hash=imagehash AND x.demo_dataset_id IS NULL) THEN score:=score+30;signals:=signals||jsonb_build_array(jsonb_build_object('code','reused_image','points',30,'detail','Image matches earlier evidence; reuse can be legitimate.')); END IF;
IF EXISTS(SELECT 1 FROM public.report_integrity r JOIN public.issues x ON x.id=r.issue_id WHERE r.request_fingerprint=fingerprint AND x.demo_dataset_id IS NULL AND x.created_at>now()-interval '1 day') THEN score:=score+25;signals:=signals||jsonb_build_array(jsonb_build_object('code','repeated_content','points',25,'detail','Same incident details recently submitted.')); END IF;
IF _report->>'duplicate_of' IS NOT NULL OR EXISTS(SELECT 1 FROM public.nearby_issues((_report->>'lat')::float8,(_report->>'lng')::float8,120,_report->>'category')) THEN score:=score+15;signals:=signals||jsonb_build_array(jsonb_build_object('code','possible_duplicate','points',15,'detail','Nearby same-category incident may match; staff decide.')); END IF;
IF coalesce((_report->>'integrity_burst')::boolean,false) THEN score:=score+15;signals:=signals||jsonb_build_array(jsonb_build_object('code','submission_burst','points',15,'detail','Several submissions in a short window.')); END IF;
IF coalesce((_report->>'integrity_location_mismatch')::boolean,false) THEN score:=score+20;signals:=signals||jsonb_build_array(jsonb_build_object('code','location_inconsistency','points',20,'detail','Unverified address or photo information differs from the confirmed incident point.')); END IF;
IF length(trim(coalesce(_report->>'description','')))<10 AND _report->>'category'='other' THEN score:=score+10;signals:=signals||jsonb_build_array(jsonb_build_object('code','incomplete_details','points',10,'detail','More incident detail could help verification.')); END IF;
score:=least(score,100);nextstate:=CASE WHEN score>=(cfg->>'review_threshold')::int THEN 'pending_review' ELSE 'unverified' END;
result:=public.create_civic_report_core(_report,_token);SELECT * INTO i FROM public.issues WHERE ref_code=result->>'ref';
INSERT INTO public.report_integrity(issue_id,state,risk_score,signals,request_fingerprint,image_hash,session_hash) VALUES(i.id,nextstate,score,signals,fingerprint,imagehash,reservation.session_hash);
UPDATE public.report_upload_reservations SET consumed=true,request_fingerprint=fingerprint WHERE key=reservation.key;
IF nextstate='pending_review' THEN INSERT INTO public.issue_events(issue_id,kind,note,actor_label) VALUES(i.id,'integrity_review','Report saved. Some details need verification; this is not a finding of wrongdoing.','Siddhi');END IF;
RETURN result; END $$;
REVOKE ALL ON FUNCTION public.create_civic_report(jsonb,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.create_civic_report(jsonb,text) TO service_role;
CREATE OR REPLACE FUNCTION public.review_report_integrity(_issue uuid,_expected text,_decision text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.issues;r public.report_integrity;ns text;st public.issue_status; BEGIN
IF NOT public.is_supervisor(auth.uid()) OR NOT public.staff_can_work(auth.uid(),_issue) THEN RAISE EXCEPTION 'Active in-scope supervisor required'; END IF;
IF _decision NOT IN ('verify','request_information','invalid') OR length(trim(coalesce(_reason,''))) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'A decision and reason of 5 to 1000 characters are required'; END IF;
SELECT * INTO i FROM public.issues WHERE id=_issue FOR UPDATE;SELECT * INTO r FROM public.report_integrity WHERE issue_id=_issue FOR UPDATE;
IF i.id IS NULL THEN RAISE EXCEPTION 'Report unavailable'; END IF;
IF r.issue_id IS NULL THEN INSERT INTO public.report_integrity(issue_id) VALUES(_issue);SELECT * INTO r FROM public.report_integrity WHERE issue_id=_issue; END IF;
IF r.state IS DISTINCT FROM _expected THEN RAISE EXCEPTION 'Review changed; refresh before deciding'; END IF;
ns:=CASE _decision WHEN 'verify' THEN 'verified' WHEN 'invalid' THEN 'invalid' ELSE 'information_requested' END;st:=i.status;
IF _decision='invalid' THEN IF i.status IN ('resolved','closed') THEN RAISE EXCEPTION 'Completed reports require existing reopening workflow';END IF; st:='rejected';ELSIF _decision='verify' AND i.status='rejected' AND r.state IN ('invalid','appealed') THEN st:='reopened'; END IF;
UPDATE public.report_integrity SET state=ns,review_reason=trim(_reason),reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() WHERE issue_id=_issue;
IF st IS DISTINCT FROM i.status THEN UPDATE public.issues SET status=st WHERE id=_issue;END IF;
INSERT INTO public.report_integrity_audit(issue_id,actor_id,actor_label,action,reason,from_state,to_state,from_status,to_status) VALUES(_issue,auth.uid(),public.staff_actor_label(auth.uid()),_decision,trim(_reason),r.state,ns,i.status,st);
INSERT INTO public.issue_events(issue_id,kind,from_status,to_status,note,actor_id,actor_label) VALUES(_issue,'integrity_'||_decision,i.status,st,trim(_reason),auth.uid(),public.staff_actor_label(auth.uid()));END $$;
REVOKE ALL ON FUNCTION public.review_report_integrity(uuid,text,text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.review_report_integrity(uuid,text,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.report_integrity_status(_ref text,_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT public.verify_reporter_token(_ref,_token) THEN RAISE EXCEPTION 'Private tracking link required'; END IF;
RETURN(SELECT jsonb_build_object('state',r.state,'reason',r.review_reason,'updated_at',r.updated_at) FROM public.report_integrity r JOIN public.issues i ON i.id=r.issue_id WHERE i.ref_code=_ref);END $$;
REVOKE ALL ON FUNCTION public.report_integrity_status(text,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.report_integrity_status(text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.citizen_integrity_response(_ref text,_token text,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.issues;r public.report_integrity;ns text;BEGIN
SELECT * INTO i FROM public.issues WHERE ref_code=_ref FOR UPDATE;
IF i.id IS NULL OR NOT public.verify_reporter_token(_ref,_token) THEN RAISE EXCEPTION 'Private tracking link required'; END IF;
IF length(trim(coalesce(_note,''))) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'Please provide 5 to 1000 characters';END IF;
SELECT * INTO r FROM public.report_integrity WHERE issue_id=i.id FOR UPDATE;
IF r.state NOT IN ('invalid','information_requested') THEN RAISE EXCEPTION 'No correction or appeal is currently requested';END IF;
ns:=CASE WHEN r.state='invalid' THEN 'appealed' ELSE 'pending_review' END;
UPDATE public.report_integrity SET state=ns,updated_at=now() WHERE issue_id=i.id;
INSERT INTO public.report_integrity_audit(issue_id,actor_label,action,reason,from_state,to_state,from_status,to_status) VALUES(i.id,'Original reporter','citizen_response',trim(_note),r.state,ns,i.status,i.status);
INSERT INTO public.issue_events(issue_id,kind,note,actor_label,visibility) VALUES(i.id,'integrity_response',trim(_note),'Original reporter','internal');END $$;
REVOKE ALL ON FUNCTION public.citizen_integrity_response(text,text,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.citizen_integrity_response(text,text,text) TO service_role;
DO $guard$ DECLARE s text; BEGIN s:=pg_get_functiondef('public.review_issue_duplicate(uuid,uuid,text,text)'::regprocedure);s:=replace(s,'IF NOT public.is_staff(auth.uid()) THEN','IF NOT public.is_supervisor(auth.uid()) OR NOT public.staff_can_work(auth.uid(),_report) OR NOT public.staff_can_work(auth.uid(),_candidate) THEN');EXECUTE s;END $guard$;
REVOKE EXECUTE ON FUNCTION public.consume_civic_request(text,integer) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.consume_civic_request(text,integer) TO service_role;